import * as THREE from 'three';
export function bedBoard(snapshot,rooms){
 const cases=snapshot?.active?snapshot.patients:[];
 const rows=rooms.map(room=>{const beds=room.id.split('/').map(id=>{const p=cases.find(p=>p.destination===id),arrived=p?.state==='bed',referred=p&&['referral-transfer','helipad-transfer','airborne'].includes(p.state),enRoute=p&&['patient-pickup','loading-walk','loading','aboard','unloading','reception','hospital-walk','bed-transfer'].includes(p.state);return {id,patient:p?.id??null,received:!!p?.admitted,state:referred?'referred':arrived?'arrived':enRoute?'en-route':'waiting'};});const count=beds.filter(b=>b.received).length;return {...room,beds,count,complete:count===2};});
 return {rooms:rows,arrived:rows.reduce((n,r)=>n+r.count,0),occupied:rows.flatMap(r=>r.beds).filter(b=>b.state==='arrived').length,complete:rows.filter(r=>r.complete).length,time:snapshot?.time||0,active:!!snapshot?.active};
}
export function createDashboard({scene,facility,open}){
 const root=new THREE.Group();root.position.set(6.25,facility.floorHeight,-16.1);scene.add(root);
 const metal=new THREE.MeshStandardMaterial({color:'#2d444b',metalness:.5,roughness:.35});
 function box(x,y,z,w,h,d){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),metal);m.position.set(x,y,z);m.castShadow=true;root.add(m);return m;}
 box(0,2.3,0,3.3,1.94,.13);box(0,.99,-.015,.12,1.8,.12);box(0,.09,0,1.6,.12,.72);
 const canvas=document.createElement('canvas');canvas.width=1920;canvas.height=1080;const ctx=canvas.getContext('2d'),texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;
 const screen=new THREE.Mesh(new THREE.PlaneGeometry(3.14,1.78),new THREE.MeshBasicMaterial({map:texture}));screen.position.set(0,2.3,.072);root.add(screen);screen.userData.bedDashboard=true;
 facility.colliders.push({minX:4.35,maxX:8.15,minZ:-16.7,maxZ:-15.6});
 const dialog=document.getElementById('bed-dashboard'),cards=document.getElementById('room-cards');let signature='',state;
 cards.innerHTML=facility.roomData.map(r=>'<article class="room-card" data-room="'+r.id+'" style="--zone:'+r.color+'"><div class="room-card-title"><b>Zone '+r.zone+' · '+r.id+'</b><span data-room-count>0 / 2</span></div><div class="room-progress"><i></i></div><p data-room-state>بانتظار وصول الحالات</p>'+r.id.split('/').map(id=>'<div class="bed-row" data-bed="'+id+'"><b>'+id+'</b><span class="bed-light"></span><span data-bed-state>بانتظار الحالة</span><small data-bed-patient></small></div>').join('')+'</article>').join('');
 function text(value,x,y,size=28,color='#d8e6e6',align='right'){ctx.font=(size>=30?'bold ':'')+size+'px Arial, Tahoma';ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(value,x,y);}
 function paint(){ctx.fillStyle='#102e35';ctx.fillRect(0,0,1920,1080);text('UQUDCM · BED MANAGEMENT',70,80,24,'#76a99e','left');text('لوحة الغرف والأسرّة',1840,135,60,'#f5faf5');text(state.arrived+' / 16 تم استلامها     ·     '+state.complete+' / 8 غرف     ·     الإشغال '+state.occupied,1840,205,34,'#8ed9b3');
  state.rooms.forEach((r,i)=>{const col=3-i%4,row=Math.floor(i/4),x=62+col*454,y=270+row*315,w=430,h=285;ctx.fillStyle='#1a3b43';ctx.beginPath();ctx.roundRect(x,y,w,h,14);ctx.fill();ctx.fillStyle=r.color;ctx.fillRect(x,y,w,9);text('Zone '+r.zone+' · '+r.id,x+w-22,y+60,30,'#f4faf8');text(r.complete?'مكتملة ✓':r.count?'جارٍ الاستقبال':'بانتظار الحالات',x+w-22,y+104,25,r.complete?'#84dab1':'#a6bdc0');r.beds.forEach((b,j)=>{const by=y+157+j*57;ctx.fillStyle=b.state==='arrived'?'#28684f':b.state==='referred'?'#5f4970':b.state==='en-route'?'#2c617a':'#28444b';ctx.beginPath();ctx.roundRect(x+20,by-30,w-40,46,6);ctx.fill();text(b.id,x+40,by,24,'#fff','left');text(b.state==='arrived'?'تم الاستلام':b.state==='referred'?'شاغر · أحيلت الحالة':b.state==='en-route'?'في الطريق':'بانتظار الوصول',x+w-36,by,24,b.state==='arrived'?'#c3f4d3':'#d7e5e8');});});
  text('الاكتمال لاستلام الحالتين · يُحدَّث الإشغال بعد الإحالة',1840,994,30,'#a6c5c2');text('اضغط الشاشة لفتح التفاصيل',1840,1042,25,'#7fa99f');texture.needsUpdate=true;
 }
 function update(snapshot){state=bedBoard(snapshot,facility.roomData);const next=JSON.stringify([state.active,state.rooms.map(r=>r.beds.map(b=>[b.state,b.patient]))]);if(next===signature)return;signature=next;paint();document.getElementById('board-total').textContent=state.arrived+' / 16';document.getElementById('board-occupied').textContent=state.occupied+' / 16';document.getElementById('board-complete').textContent=state.complete+' / 8';document.getElementById('sim-room-count').innerHTML='<b dir="ltr">'+state.complete+' / 8</b> غرف';document.getElementById('sim-bed-count').innerHTML='<b dir="ltr">'+state.occupied+' / 16</b> مشغولاً';
  for(const r of state.rooms){const card=[...cards.children].find(c=>c.dataset.room===r.id);card.classList.toggle('complete',r.complete);card.querySelector('[data-room-count]').textContent=r.count+' / 2';card.querySelector('.room-progress i').style.width=r.count*50+'%';card.querySelector('[data-room-state]').textContent=r.complete?'مكتملة — تم استلام الحالتين':r.count?'تم استلام حالة · بانتظار الثانية':'بانتظار وصول الحالات';for(const b of r.beds){const row=card.querySelector('[data-bed="'+b.id+'"]');row.dataset.state=b.state;row.querySelector('[data-bed-state]').textContent=b.state==='arrived'?'تم الاستلام':b.state==='referred'?'شاغر · أحيلت الحالة':b.state==='en-route'?'في الطريق':'بانتظار الوصول';row.querySelector('[data-bed-patient]').textContent=b.patient||'—';}}
 }
 update(null);
 return {root,screen,texture,update,get state(){return state},open:()=>open(dialog.id)};
}
